examples.setup:
val handbook = MonarchAiSourcePart(id = "s1", title = "Team handbook", url = "https://example.com/handbook", kind = MonarchAiSourceKind.Doc, product = "Docs")
val policy = MonarchAiSourcePart(id = "s2", title = "Support policy", url = "https://example.com/support-policy", kind = MonarchAiSourceKind.Web)
var previewed by remember { mutableStateOf<MonarchAiSourcePart?>(null) }

examples.code:
Text(
    text = buildAnnotatedString {
        append("Requests are answered within two working days" + " ")
        appendInlineContent("first")
        append(", and urgent issues have a separate queue")
        appendInlineContent("second")
        append(".")
    },
    style = MonarchTheme.typography.body,
    inlineContent = mapOf(
        "first" to InlineTextContent(Placeholder(28.sp, 20.sp, PlaceholderVerticalAlign.Center)) {
            MonarchAiCitation(index = 1, source = handbook, quote = "Requests are answered within two working days.", onOpen = { previewed = it })
        },
        "second" to InlineTextContent(Placeholder(28.sp, 20.sp, PlaceholderVerticalAlign.Center)) {
            MonarchAiCitation(index = 2, source = policy)
        },
    ),
)
previewed?.let { source ->
    MonarchBottomSheet(onDismissRequest = { previewed = null }) {
        MonarchAiSourcePreview(
            source = source,
            quote = "Requests are answered within two working days.",
            content = "Welcome to the team.\n\nRequests are answered within two working days. Urgent issues go to the on-call queue.\n\nSee the support policy for details.",
            onClose = { previewed = null },
        )
    }
}
